Loss.create!([
  {date: "2016-07-21 04:00:00", amount: "100000000.0", title: "NBA will move 2017 All-Star Game from Charlotte over HB2 law", slug: "nba-all-star-game", description: "", template: "NC loses even more money due to HB2.Contributing $100,000,000 to the total of $169,100,000, the loss of this eventis unfortunate.\n\nIn a statement by NBA\n\n <blockquote class=\"template-quote\">\nWhile we recognize that the NBA cannot choose the law in every city, state, and country in which we do business, we do not believe we can successfully host our All-Star festivities in Charlotte in the climate created by HB2,” as the law is commonly known.\n</blockquote>\n<a class=\"template-quote-source\" href=\"\">\nView full statement\n</a>\n\n", sources: nil},
  {date: "2016-04-15 04:00:00", amount: nil, title: "Cirque Du Soleil cancels performances in North Carolina", slug: "cirque-du-soleil", description: "Cirque Du Soleil announced they will not perform in North Carolina due to HB2.", template: "Playing around with this thing on 2,016-04-15T04:00:00.000Z in the amount of .", sources: nil},
  {date: "2016-04-04 04:00:00", amount: "3000000.0", title: "Lionsgate takes 100 jobs from NC due to HB2", slug: "lionsgate", description: "", template: "Playing around with this narrative on 2,016T04:00:00.000Z in the amount of 3,000,000.", sources: nil},
  {date: "2016-04-18 04:00:00", amount: nil, title: "Pearl Jam show in Raleigh cancelled over HB2", slug: "pearl-jam", description: "Pearl Jam cancels Raleigh concert over HB2", template: "NC loses even more money due to HB2.Contributing $ to the total of $169,100,000, the loss of this concertis unfortunate.\n\nIn a statement by Pearl Jamreleased via Facebook,\n\n <blockquote class=\"template-quote\">\nThe HB2 law that was recently passed is a despicable piece of legislation that encourages discrimination against an entire group of American citizens. The practical implications are expansive and its negative impact upon basic human rights is profound. We want America to be a place where no one can be turned away from a business because of who they love or fired from their job for who they are.\n</blockquote>\n<a class=\"template-quote-source\" href=\"https://www.facebook.com/PearlJam/posts/10154115448802485:0\">\nView full statement\n</a>\n\n", sources: nil},
  {date: "2016-04-12 04:00:00", amount: "21400000.0", title: "Deutsche Bank's Cary expansion cancelled", slug: "deutsche-bank", description: "After freezing jobs expansion in Cary over HB2, Deutsche Bank moves ahead with Florida expansion", template: "NC loses even more money due to HB2.Contributing $21,400,000 to the total of $169,100,000, the loss of this company expansionis unfortunate.\n\nIn a statement by John Cryan\n\n <blockquote class=\"template-quote\">\nWe take the commitment to building inclusive work environments seriously. We’re proud of our operations and employees in Cary and regret that as a result of this legislation we are unwilling to include North Carolina in our U.S. expansion plans for now. We very much hope to revisit our plans to grow this location in the near future.\n</blockquote>\n<a class=\"template-quote-source\" href=\"https://www.db.com/usa/content/en/3639.html\">\nView full statement\n</a>\n\n", sources: nil},
  {date: "2016-04-18 04:00:00", amount: nil, title: "Boston cancels all North Carolina shows", slug: "boston", description: "Boston cancels North Carolina tour dates due to HB2", template: "NC loses even more money due to HB2.Contributing $ to the total of $169,100,000, the loss of this concertis unfortunate.\n\nIn a statement by Tom Scholzreleased via Facebook,\n\n <blockquote class=\"template-quote\">\nHB2 has the appearance of an oppressive discriminatory law against a small minority, who already have to deal with a narrow-minded world regarding issues beyond their control which they did nothing to bring upon themselves.\n</blockquote>\n<a class=\"template-quote-source\" href=\"https://www.facebook.com/bandboston/posts/1176004065772990\">\nView full statement\n</a>\n\n", sources: nil},
  {date: "2016-04-05 04:00:00", amount: "44000000.0", title: "Paypal withdraws investment in North Carolina", slug: "paypal", description: "", template: "Here's another unfortunate loss for the state of North Carolina.Contributing $44,000,000 to the total of $169,100,000, the loss of this company expansionis unfortunate.\n\nIn a statement by Dan Schulman\n\n <blockquote class=\"template-quote\">\nThe new law perpetuates discrimination and it violates the values and principles that are at the core of PayPal’s mission and culture.  As a result, PayPal will not move forward with our planned expansion into Charlotte.\n</blockquote>\n<a class=\"template-quote-source\" href=\"https://www.paypal.com/stories/us/paypal-withdraws-plan-for-charlotte-expansion\">\nView full statement\n</a>\n\n", sources: nil},
  {date: "2016-04-08 04:00:00", amount: "700000.0", title: "Bruce Springsteen Cancels North Carolina Concert Over Anti-Gay Bill", slug: "bruce-springsteen", description: "Springsteen was scheduled to play Greensboro, but said he finds the passing of House Bill 2 unacceptable, and he is doing his part to push back.", template: "Here's another unfortunate loss for the state of North Carolina.Contributing $700,000 to the total of $169,100,000, the loss of this concertis unfortunate.\n\nIn a statement by Bruce Springsteen\n\n <blockquote class=\"template-quote\">\nSome things are more important than a rock show and this fight against prejudice and bigotry — which is happening as I write — is one of them. It is the strongest means I have for raising my voice in opposition to those who continue to push us backwards instead of forwards.\n</blockquote>\n<a class=\"template-quote-source\" href=\"http://brucespringsteen.net/news/2016/a-statement-from-bruce-springsteen-on-north-carolina\">\nView full statement\n</a>\n\n", sources: nil}
])

